mapper.select:
SELECT d.id, d.dict_type_id, COALESCE(l.field_value, d.dict_label) as 'dictLabel', d.dict_value, d.attr_type, d.remark, d.sort, d.updated_by, d.updated_at, d.created_by, d.created_at FROM sys_dict_data d LEFT JOIN sys_language l ON l.table_name = 'sys_dict_data' and l.field_name = 'label' and d.id = l.table_id AND l.`language` = #{language}
AND l.field_value like concat("%", #{dictLabel}, "%")
d.dict_type_id = #{dictTypeId}
AND d.dict_label like concat("%", #{dictLabel}, "%")
AND d.dict_value like concat("%", #{dictValue}, "%")
ORDER BY d.sort ASC

SELECT d.dict_type_id, COALESCE(l.field_value, d.dict_label) as 'dictLabel', d.dict_value, d.attr_type
FROM sys_dict_data d LEFT JOIN sys_language l
ON l.table_name = 'sys_dict_data' and l.field_name = 'label' and d.id = l.table_id AND l.`language` = #{language}

    LEFT JOIN sys_dict_type t ON d.dict_type_id = t.id
    WHERE t.dict_type = #{dictType}

ORDER BY d.dict_type_id, d.sort
